ing:14px 16px; border-bottom:1px solid var(--color-border); color:var(--color-error); }\n.docs-loading { padding:24px 16px; color:var(--color-text-maxcontrast); }\n\n.docs-table {\n\twidth: 100%;\n\tborder-collapse: collapse;\n\tfont-size: 13px;\n}\n\n.docs-table th,\n.docs-table td {\n\ttext-align: left;\n\tpadding: 8px 12px;\n\tborder-bottom: 1px solid var(--color-border);\n}\n\n.docs-table th {\n\tcolor: var(--color-text-maxcontrast);\n\tfont-weight: 600;\n}\n\n.docs-caret-head {\n\twidth: 28px;\n}\n\n.docs-row {\n\tcursor: pointer;\n}\n\n.docs-row:hover td {\n\tbackground: var(--color-background-hover);\n}\n\n.docs-row:focus-visible td {\n\toutline: 2px solid var(--color-primary-element);\n\toutline-offset: -2px;\n}\n\n.docs-row.open td {\n\tbackground: var(--color-background-hover);\n}\n\n.docs-caret {\n\twidth: 28px;\n\tcolor: var(--color-text-maxcontrast);\n}\n\n.docs-progress {\n\tmargin: 4px 0 10px;\n\tfont-size: 13px;\n\tcolor: var(--color-text-maxcontrast);\n}\n\n.docs-path {\n\tmin-width: 160px;\n}\n\n.docs-path-inner {\n\toverflow: hidden;\n\ttext-overflow: ellipsis;\n\tmax-width: 420px;\n\tdisplay: inline-block;\n\tvertical-align: middle;\n}\n\n\n.docs-mime {\n\tcolor: var(--color-text-maxcontrast);\n}\n\n.docs-chunks {\n\ttext-align: center;\n}\n\n.docs-date {\n\tcolor: var(--color-text-maxcontrast);\n\twhite-space: nowrap;\n}\n\n.docs-chunkrow td {\n\tbackground: var(--color-background-hover);\n\tpadding: 4px 12px 14px;\n}\n\n.docs-chunklist {\n\tmax-height: min(58vh, 720px);\n\toverflow-y: auto;\n}\n\n.docs-chunk {\n\tdisplay: flex;\n\tgap: 10px;\n\tpadding: 8px 10px;\n\tmargin-bottom: 6px;\n\tbackground: var(--color-main-background);\n\tborder: 1px solid var(--color-border);\n\tborder-radius: 8px;\n\tfont-size: 12px;\n}\n\n.docs-chunk-idx {\n\tflex-shrink: 0;\n\tfont-family: monospace;\n\tfont-weight: 700;\n\tcolor: var(--color-primary-element);\n}\n\n.docs-chunk-text {\n\twhite-space: pre-wrap;\n\tword-break: break-word;\n\tmax-height: 140px;\n\to